package main

import (
	"encoding/binary"
	"fmt"
	"io"
	"net/http"
	"os"
	"unsafe"
)

// BuildArtifactHeader represents the header of a CI/CD build artifact
type BuildArtifactHeader struct {
	Magic      uint32
	Version    uint16
	NumChunks  uint16
	ChunkSize  uint32
	TotalSize  uint32
	Checksum   uint32
}

const (
	ARTIFACT_MAGIC = 0xBEEFCAFE
	MAX_ARTIFACT_SIZE = 1024 * 1024 * 512 // 512MB
)

// ProcessArtifact handles incoming build artifacts from the pipeline
func ProcessArtifact(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Read the artifact header
	var header BuildArtifactHeader
	err := binary.Read(r.Body, binary.LittleEndian, &header)
	if err != nil {
		http.Error(w, "Invalid header", http.StatusBadRequest)
		return
	}

	if header.Magic != ARTIFACT_MAGIC {
		http.Error(w, "Invalid magic bytes", http.StatusBadRequest)
		return
	}

	// VULNERABILITY: Integer overflow in allocation size calculation
	// NumChunks (uint16) * ChunkSize (uint32) can overflow uint32
	// When NumChunks=65535 and ChunkSize=65538, the multiplication
	// overflows to a small value, but actual data written is huge
	allocSize := uint32(header.NumChunks) * header.ChunkSize

	// This check passes due to overflow
	if allocSize > uint32(MAX_ARTIFACT_SIZE) {
		http.Error(w, "Artifact too large", http.StatusRequestEntityTooLarge)
		return
	}

	fmt.Printf("[pipeline-plugin] Allocating %d bytes for %d chunks of size %d\n",
		allocSize, header.NumChunks, header.ChunkSize)

	// Allocate buffer based on overflowed size
	buf := make([]byte, allocSize)

	// Read actual data - this reads far more than allocated buffer
	// In Go, this causes slice bounds out of range panic or
	// with unsafe operations below, heap corruption
	var totalRead uint32
	for i := uint16(0); i < header.NumChunks; i++ {
		chunkBuf := make([]byte, header.ChunkSize)
		n, err := io.ReadFull(r.Body, chunkBuf)
		if err != nil && err != io.ErrUnexpectedEOF {
			break
		}
		// Unsafe copy into pre-allocated buffer - heap overflow
		if totalRead+uint32(n) <= allocSize {
			copy(buf[totalRead:], chunkBuf[:n])
		} else {
			// Unsafe pointer arithmetic - writes beyond buffer
			dst := unsafe.Pointer(unsafe.SliceData(buf))
			dstOffset := unsafe.Add(dst, uintptr(totalRead))
			src := unsafe.Pointer(unsafe.SliceData(chunkBuf))
			copyUnsafe(dstOffset, src, uintptr(n))
		}
		totalRead += uint32(n)
	}

	// Write artifact to staging
	stagingPath := fmt.Sprintf("/tmp/artifacts/%x.bin", header.Checksum)
	os.WriteFile(stagingPath, buf, 0644)

	w.WriteHeader(http.StatusAccepted)
	fmt.Fprintf(w, "{\"status\": \"accepted\", \"size\": %d}", totalRead)
}

//go:nosplit
func copyUnsafe(dst, src unsafe.Pointer, n uintptr) {
	for i := uintptr(0); i < n; i++ {
		*(*byte)(unsafe.Add(dst, i)) = *(*byte)(unsafe.Add(src, i))
	}
}

func main() {
	http.HandleFunc("/api/v1/artifacts/upload", ProcessArtifact)
	http.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte("ok"))
	})

	port := os.Getenv("PLUGIN_PORT")
	if port == "" {
		port = "8080"
	}

	fmt.Printf("[pipeline-plugin] Starting artifact processor on :%s\n", port)
	http.ListenAndServe(":"+port, nil)
}
